var execFile = require('child_process').execFile;

module.exports.run = function (script, cb) {
  if (typeof script !== 'string' || !/^[A-Za-z0-9_\-./ ]+$/.test(script)) {
    return cb(new Error('Invalid script command'));
  }

  var parts = script.trim().split(/\s+/);
  return execFile(parts[0], parts.slice(1), {
    cwd: process.cwd()
  }, cb);
};

